scmBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "scmBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "scmfamily",
                name = "scm",
                version = c(1,0,0),
                options = options,
                results = scmResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Synthetic Control
#'
#' 
#' @param data .
#' @param outcome .
#' @param unit Identifier of the cross-sectional unit (e.g. state or country)
#' @param time Time period (numeric year or period index)
#' @param treatedUnit .
#' @param treatmentTime .
#' @param predictors Covariates averaged over the pre-treatment period. If
#'   empty, pre-treatment outcomes are used as predictors.
#' @param placebo .
#' @param placeboPreRatio Placebos whose pre-treatment RMSPE exceeds this
#'   multiple of the treated unit's are excluded from the filtered p-value and
#'   the gap plot.
#' @param looCheck .
#' @param looFig .
#' @param timingCheck .
#' @param timingFig .
#' @param preLengthCheck .
#' @param preLengthFig .
#' @param intimeCheck .
#' @param intimeFig .
#' @param donorExclude Units to remove from the donor pool in all analyses,
#'   e.g. states with confounding policies.
#' @param optStarts .
#' @param seed .
#' @param timingOffsets .
#' @param preLengthDrops .
#' @param intimeOffsets .
#' @param looSubset .
#' @param predictorStat .
#' @param showHelp .
#' @param pValueMethod .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$permTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$weights} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$balance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pathsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$gapsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$weightsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$looTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$looPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$timingTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$timingPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$preLengthTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$preLengthPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$intimeTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$intimePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$placeboState} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$looState} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$timingState} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$preLengthState} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$intimeState} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
scm <- function(
    data,
    outcome,
    unit,
    time,
    treatedUnit,
    treatmentTime = 2000,
    predictors,
    placebo = FALSE,
    placeboPreRatio = 2,
    looCheck = FALSE,
    looFig = FALSE,
    timingCheck = FALSE,
    timingFig = FALSE,
    preLengthCheck = FALSE,
    preLengthFig = FALSE,
    intimeCheck = FALSE,
    intimeFig = FALSE,
    donorExclude = "",
    optStarts = 5,
    seed = 1,
    timingOffsets = "-2,-1,1,2",
    preLengthDrops = "0,2,4,6",
    intimeOffsets = "-6,-4,-2",
    looSubset = "",
    predictorStat = "mean",
    showHelp = FALSE,
    pValueMethod = "ratio",
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("scm requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(unit)) unit <- jmvcore::resolveQuo(jmvcore::enquo(unit))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(predictors)) predictors <- jmvcore::resolveQuo(jmvcore::enquo(predictors))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(unit), unit, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(predictors), predictors, NULL))


    options <- scmOptions$new(
        outcome = outcome,
        unit = unit,
        time = time,
        treatedUnit = treatedUnit,
        treatmentTime = treatmentTime,
        predictors = predictors,
        placebo = placebo,
        placeboPreRatio = placeboPreRatio,
        looCheck = looCheck,
        looFig = looFig,
        timingCheck = timingCheck,
        timingFig = timingFig,
        preLengthCheck = preLengthCheck,
        preLengthFig = preLengthFig,
        intimeCheck = intimeCheck,
        intimeFig = intimeFig,
        donorExclude = donorExclude,
        optStarts = optStarts,
        seed = seed,
        timingOffsets = timingOffsets,
        preLengthDrops = preLengthDrops,
        intimeOffsets = intimeOffsets,
        looSubset = looSubset,
        predictorStat = predictorStat,
        showHelp = showHelp,
        pValueMethod = pValueMethod,
        showGuide = showGuide)

    analysis <- scmClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

